-- Euresis customer account core schema
create extension if not exists pgcrypto;
create table public.customer_profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', phone text not null default '', company text not null default '', country text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_vehicles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, make text not null, model text not null, model_year text not null default '', trim text not null default '', notes text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, label text not null default 'Home', recipient text not null, phone text not null default '', country text not null, region text not null default '', city text not null, postal_code text not null default '', line1 text not null, line2 text not null default '', is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index customer_addresses_one_default_per_user on public.customer_addresses(user_id) where is_default;
create table public.customer_preferences (user_id uuid primary key references auth.users(id) on delete cascade, language text not null default 'English', currency text not null default 'USD', units text not null default 'Metric (mm)', contact_method text not null default 'Email', product_updates boolean not null default true, updated_at timestamptz not null default now());
create table public.customer_enquiries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, reference text not null unique default ('ENQ-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))), subject text not null, message text not null, status text not null default 'received' check (status in ('received','in_review','replied','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_after_sales_cases (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, reference text not null unique default ('AS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))), subject text not null, description text not null, status text not null default 'submitted' check (status in ('submitted','in_review','awaiting_customer','resolved','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, order_number text not null unique, status text not null default 'confirmed' check (status in ('confirmed','in_production','quality_check','dispatched','delivered','cancelled')), carrier text not null default '', tracking_number text not null default '', estimated_dispatch_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.customer_orders(id) on delete cascade, product_name text not null, specification text not null default '', quantity integer not null default 1 check (quantity > 0));
create table public.customer_order_events (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.customer_orders(id) on delete cascade, status text not null, description text not null default '', occurred_at timestamptz not null default now());
create index customer_vehicles_user_idx on public.customer_vehicles(user_id);
create index customer_addresses_user_idx on public.customer_addresses(user_id);
create index customer_enquiries_user_created_idx on public.customer_enquiries(user_id, created_at desc);
create index customer_after_sales_user_created_idx on public.customer_after_sales_cases(user_id, created_at desc);
create index customer_orders_user_created_idx on public.customer_orders(user_id, created_at desc);
create index customer_order_items_order_idx on public.customer_order_items(order_id);
create index customer_order_events_order_idx on public.customer_order_events(order_id, occurred_at);
create or replace function public.handle_new_customer() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.customer_profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; insert into public.customer_preferences(user_id) values(new.id) on conflict(user_id) do nothing; return new; end; $$;
create trigger on_auth_user_created_customer after insert on auth.users for each row execute procedure public.handle_new_customer();
revoke execute on function public.handle_new_customer() from public, anon, authenticated;
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at=now(); return new; end; $$;
do $$ declare t text; begin foreach t in array array['customer_profiles','customer_vehicles','customer_addresses','customer_preferences','customer_enquiries','customer_after_sales_cases','customer_orders'] loop execute format('create trigger %I before update on public.%I for each row execute procedure public.set_updated_at()',t || '_updated_at',t); end loop; end $$;
alter table public.customer_profiles enable row level security;
alter table public.customer_vehicles enable row level security;
alter table public.customer_addresses enable row level security;
alter table public.customer_preferences enable row level security;
alter table public.customer_enquiries enable row level security;
alter table public.customer_after_sales_cases enable row level security;
alter table public.customer_orders enable row level security;
alter table public.customer_order_items enable row level security;
alter table public.customer_order_events enable row level security;
create policy "Customers can read own profile" on public.customer_profiles for select to authenticated using ((select auth.uid())=id);
create policy "Customers can insert own profile" on public.customer_profiles for insert to authenticated with check ((select auth.uid())=id);
create policy "Customers can update own profile" on public.customer_profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy "Customers manage own vehicles" on public.customer_vehicles for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Customers manage own addresses" on public.customer_addresses for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Customers read own preferences" on public.customer_preferences for select to authenticated using ((select auth.uid())=user_id);
create policy "Customers create own preferences" on public.customer_preferences for insert to authenticated with check ((select auth.uid())=user_id);
create policy "Customers update own preferences" on public.customer_preferences for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Customers read own enquiries" on public.customer_enquiries for select to authenticated using ((select auth.uid())=user_id);
create policy "Customers create own enquiries" on public.customer_enquiries for insert to authenticated with check ((select auth.uid())=user_id);
create policy "Customers read own after sales cases" on public.customer_after_sales_cases for select to authenticated using ((select auth.uid())=user_id);
create policy "Customers create own after sales cases" on public.customer_after_sales_cases for insert to authenticated with check ((select auth.uid())=user_id);
create policy "Customers read own orders" on public.customer_orders for select to authenticated using ((select auth.uid())=user_id);
create policy "Customers read own order items" on public.customer_order_items for select to authenticated using (exists(select 1 from public.customer_orders o where o.id=order_id and o.user_id=(select auth.uid())));
create policy "Customers read own order events" on public.customer_order_events for select to authenticated using (exists(select 1 from public.customer_orders o where o.id=order_id and o.user_id=(select auth.uid())));
grant usage on schema public to authenticated;
grant select,insert,update on public.customer_profiles to authenticated;
grant select,insert,update,delete on public.customer_vehicles to authenticated;
grant select,insert,update,delete on public.customer_addresses to authenticated;
grant select,insert,update on public.customer_preferences to authenticated;
grant select,insert on public.customer_enquiries,public.customer_after_sales_cases to authenticated;
grant select on public.customer_orders,public.customer_order_items,public.customer_order_events to authenticated;

-- Customer submissions cannot set their own internal workflow status.
revoke insert on public.customer_enquiries from authenticated;
grant insert (user_id, subject, message) on public.customer_enquiries to authenticated;
revoke insert on public.customer_after_sales_cases from authenticated;
grant insert (user_id, subject, description) on public.customer_after_sales_cases to authenticated;
